import { Box, Button, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeStudySmarter } from "../types/home";

const BLUE = "#759ae1";
const NAVY = "#17224d";

function Heading({ title, highlight }: { title?: string; highlight?: string }) {
  if (!title && !highlight) return null;
  if (title && highlight && title.includes(highlight)) {
    const index = title.indexOf(highlight);
    return (
      <>
        {title.slice(0, index)}
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
        {title.slice(index + highlight.length)}
      </>
    );
  }
  return (
    <>
      {title}{" "}
      {highlight ? (
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
      ) : null}
    </>
  );
}

export default function StudySmarter({ data }: { data?: HomeStudySmarter | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 9 }, backgroundColor: "#f5fafe" }}>
      <Container maxWidth="lg">
        <Typography
          sx={{
            textAlign: "center",
            color: NAVY,
            fontSize: { xs: 26, md: 36 },
            fontWeight: 700,
            lineHeight: 1.15,
            mb: { xs: 4, md: 6 },
          }}
        >
          <Heading title={data.title} highlight={data.highlight} />
        </Typography>
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems="center"
          spacing={{ xs: 4, md: 8 }}
        >
          {mediaUrl(data.image) ? (
            <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
              <Box
                component="img"
                src={mediaUrl(data.image)}
                alt={data.image?.alternativeText || data.title || "Study smarter"}
                sx={{ width: "100%", maxWidth: 426, objectFit: "cover", display: "block", mx: "auto" }}
              />
            </Box>
          ) : null}
          <Box sx={{ flex: 1, width: "100%" }}>
            <BlocksText
              content={data.description}
              sx={{
                color: "#5a6473",
                fontSize: { xs: 15, md: 17 },
                lineHeight: 1.7,
                mb: 2,
                "& strong": { fontWeight: 700 },
              }}
            />
            {data.tagline ? (
              <Typography sx={{ color: "#5a6473", fontSize: { xs: 15, md: 17 }, textAlign: "center", mb: 3 }}>
                {data.tagline}
              </Typography>
            ) : null}
            {data.buttonUrl ? (
              <Box sx={{ textAlign: "center" }}>
                <Button
                  variant="contained"
                  href={data.buttonUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  sx={{
                    width: 203,
                    backgroundColor: BLUE,
                    color: "#fff",
                    fontWeight: 700,
                    borderRadius: "5px",
                    boxShadow: "none",
                    "&:hover": { backgroundColor: "#5f86d4", boxShadow: "none" },
                  }}
                >
                  {data.buttonLabel || "Know More"}
                </Button>
              </Box>
            ) : null}
          </Box>
        </Stack>
      </Container>
    </Box>
  );
}
